import 'package:flutter/material.dart';
import 'package:http/http.dart' as http;
import 'dart:convert';
class Login extends StatefulWidget{const Login({super.key});@override State<Login> createState()=>_L();}
class _L extends State<Login>{final e=TextEditingController();final p=TextEditingController();String m='';
  Future<void> go()async{final r=await http.post(Uri.parse('{{api_url}}/login'),headers:{'Content-Type':'application/json'},body:jsonEncode({'email':e.text,'password':p.text}));setState(()=>m=r.statusCode==200?'ok':'fail');}
  @override Widget build(BuildContext c)=>Scaffold(body:Padding(padding:const EdgeInsets.all(24),child:Column(mainAxisAlignment:MainAxisAlignment.center,children:[TextField(controller:e,decoration:const InputDecoration(labelText:'email')),TextField(controller:p,obscureText:true,decoration:const InputDecoration(labelText:'password')),ElevatedButton(onPressed:go,child:const Text('Login')),Text(m)])));}
